mapper.select:
select @rownum := @rownum + 1 as rownum, ta.* from ( select tb.board_idx , tb.board_conidx , tb.board_name , tb.board_regdate , (select mem_name from tcc_member tm where tm.mem_idx = tb.mem_idx) as mem_name from tcc_board tb where tb.board_config = 'C'
and tb.${fkey} like #{fval}
) ta, ( select @rownum := #{snum} ) r order by board_conidx desc limit #{snum}, 10
